function panelAltar(){SV.altar=SV.altar||{};if(!abyssOpen())return '<h3>深淵の祭壇</h3><p class="hint" style="color:var(--pri-d)">魔界の 10周目を クリアすると ひらく。</p>';
 return '<h3>深淵の祭壇</h3><p class="hint">深淵のかけらを ささげて、ずっと 残る 力を 得る。上限は ない。段階が 上がるほど 必要な かけらが ふえる。</p><div class="stats"><div><span>深淵のかけら</span>'+(SV.abyss||0)+'</div><div><span>勇者ランク</span>'+SV.lv+'</div>'+(SV.lv>100?'<div><span>限界突破</span>×'+heroLB().toFixed(2)+'</div>':'')+'</div><div class="list">'+
 ALTAR.map(([k,n,d])=>{const lv=SV.altar[k]||0,c=altarCost(lv);return '<div class="li" style="cursor:default;align-items:center"><div class="body"><div class="t"><span>'+n+' <span class="tag">'+lv+'段</span></span><span class="d">いま '+altarTxt(k,lv)+'</span></div><div class="d">'+d+'　つぎ：'+altarTxt(k,lv+1)+'</div></div><button class="btn sm primary" data-act="altar" data-k="'+k+'"'+((SV.abyss||0)>=c?'':' disabled')+' style="white-space:nowrap">'+c+'こ</button></div>'}).join('')+'</div>'+
 '<p class="hint">勇者ランクは 100から 先、1レベル ごとに ダメージと HPが 0.6% ずつ かけ算で のびる（限界突破）。進化した 仲間は Lv99の 先も 育ち、1レベル ごとに 1% ずつ のびる。</p>'}
const fmtG=n=>n>=10000?(n/10000).toFixed(1).replace(/\.0$/,'')+'万':String(Math.floor(n));
const pct=v=>(v>=0?'+':'')+Math.round(v)+'%';
const TABS=[['go','出撃'],['waza','技'],['ally','仲間'],['gear','装備'],['job','ジョブ'],['card','カード'],['town','町'],['rec','記録'],['cfg','設定']];
