const TAB_HINT={waza:'「技」は 戦いの中で 技を ひらめくと ひらく',ally:'「仲間」は 敵が 落とす ハートを 拾うと ひらく',gear:'「装備」は 装備を 拾うと ひらく',job:'「ジョブ」は 1回 出撃すると ひらく',town:'「町」は 1回 出撃すると ひらく',rec:'「記録」は 1回 出撃すると ひらく',card:'「カード」は 敵が まれに 落とす カードを 拾うと ひらく'};
